// A heatmap: a table of values shown as colour. The markup is the table — one row per series, one cell per column, every
// value in the cell as text — and the colour is `color-mix()` between two theme colours by the cell's share of the scale.
// No SVG and no canvas: the square is the cell, and the grid is the table's rows joining one grid with `display: contents`.
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { For, createSignal } from "solid-js";

import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** What `render` gets: the props of the table, `data-part` and the caller's class merged in. */
export type HeatmapPartProps = PartProps;

/** One row of the heatmap: its label and its value per column. */
export interface HeatmapRow {
  readonly label: string;
  readonly values: ReadonlyArray<number>;
}

export interface HeatmapProps extends Renderable<HeatmapPartProps, void> {
  /** The rows, in reading order; a missing value is drawn as an empty cell. */
  readonly rows: ReadonlyArray<HeatmapRow>;
  /** The column labels: hours, days, buckets — one per value. */
  readonly columns: ReadonlyArray<string>;
  /** The table's caption, which also names it: "Requests by hour, last week". */
  readonly label: string;
  /** The top of the scale; left out, the largest value. */
  readonly max?: number;
  /** The bottom of the scale; left out, 0. */
  readonly min?: number;
  /** The noun a cell's value is read with, in the caption's second line: "requests". */
  readonly unit?: string;
  /** A cell as a reader sees it on hover; left out, the number itself. */
  readonly format?: (value: number) => string;
  readonly class?: string;
}

// The table is the grid: the label column is as wide as the longest label, every other column shares what is left. The rows
// and their groups are `display: contents`, so the cells are the grid items and the columns stay aligned across the sections
// — a table's own layout, without a table's boxes.
const table = css.cn(
  css.display("grid"),
  css.gap("2px"),
  css.width("100%"),
  css.borderCollapse("collapse"),
  css.fontSize(t.font.size),
  css.color(t.color.text),
);

// the caption is the table's first row, across every column
const caption = css.cn(
  css.gridColumn("1 / -1"),
  css.paddingBlock(t.space._1),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
);
const head = css.cn(css.display("contents"));
const body = css.cn(css.display("contents"));
const row = css.cn(css.display("contents"));

// The column labels are the header row: small, muted, and on the same grid as the cells.
const column = css.cn(
  css.padding("2px 0"),
  css.fontSize(t.font.sizeSm),
  css.fontWeight("400"),
  css.color(t.color.muted),
  css.textAlign("center"),
);

// The row label is a header cell of the grid: it stays put while the squares colour themselves.
const corner = css.cn(css.fontSize(t.font.sizeSm), css.color(t.color.muted));
const label = css.cn(
  css.paddingInlineEnd(t.space._2),
  css.fontSize(t.font.sizeSm),
  css.fontWeight("500"),
  css.textAlign("start"),
  css.whiteSpace("nowrap"),
);

// One square. `min-height: 0` lets the value shown on hover overflow a small cell instead of stretching its row; the value
// itself is the cell's text, hidden at rest and shown over the square.
const cell = css.cn(
  css.group(),
  css.position("relative"),
  css.aspectRatio("1"),
  css.minWidth("0"),
  css.minHeight("0"),
  css.borderRadius("2px"),
  css.bg(
    "color-mix(in oklab, var(--heat-hot) calc((var(--v) - var(--min)) / (var(--max) - var(--min)) * 100%), var(--heat-cold))",
  ),
);

// The numbers view: the square grows to its row, the colour steps aside and the value is text in place. It is a class the
// host's own toggle swaps, not a media or attribute condition — the state is a control's, and a checkbox cannot reach a
// sibling without `:has()`, which the engine does not offer.
const cellOpen = css.cn(
  cell,
  css.aspectRatio("auto"),
  css.padding("2px 6px"),
  css.textAlign("end"),
  css.bg(t.color.surface),
  css.border("1px solid", t.color.border),
);

const empty = css.cn(cell, css.bg(t.color.buttonBackground));

// The value is the cell's own text: at rest it is there for a reader and out of the way of the colour, and the pointer's
// sample shows it over the square. It is a span so the hide/show is a rule of its own, and `inset: 0` keeps the square's size.
const text = css.cn(
  css.position("absolute"),
  css.inset("0"),
  css.display("flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.fontSize("0"),
  css.lineHeight(1),
  css.whiteSpace("nowrap"),
  css.color(t.color.text),
  css.pointerEvents("none"),
  css.within(css.hover)(
    css.position("relative"),
    css.zIndex("1"),
    css.paddingInline(t.space._1),
    css.fontSize(t.font.sizeSm),
    css.bg(t.color.surface),
    css.borderRadius("2px"),
  ),
);

// In the numbers view every value is visible in place, with nothing to hover.
const textOpen = css.cn(
  text,
  css.position("static"),
  css.fontSize(t.font.size),
  css.bg("transparent"),
  css.pointerEvents("auto"),
  css.opacity(1),
);

// The switch: one button, `aria-pressed` says which view is on, and it is the only state the component owns.
const toggle = css.cn(
  css.width("max-content"),
  css.padding("2px 8px"),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.sm),
  css.bg(t.color.surface),
  css.color(t.color.text),
  css.fontSize(t.font.sizeSm),
  css.cursor("pointer"),
  css.attr("aria-pressed", "true")(css.bg(t.color.highlight), css.color(t.color.onHighlight)),
);

const scale = css.cn(css.margin("0"), css.fontSize(t.font.sizeSm), css.color(t.color.muted));
const toggles = css.cn(css.justifySelf("start"));

// The figure fills the page it is on: a table of 24 columns does not shrink to its caption, and the preview centres its items.
const frame = css.cn(css.display("grid"), css.width("100%"), css.margin(0), css.gap(t.space._1));

/**
 * A heatmap: values across two dimensions, as a table whose cells are coloured by their share of the scale.
 *
 * The colours are two theme colours mixed by the value, so a tint or a theme moves the whole map; the table is the data, and
 * a reader on a screen reader or with the stylesheet off gets the rows, the headers and the numbers.
 */
export const Heatmap = (props: HeatmapProps): JSX.Element => {
  // the one thing the component owns: which of the two views is on
  const [numbers, setNumbers] = createSignal(false);
  const values = (): ReadonlyArray<number> =>
    props.rows.flatMap((entry) => entry.values).filter((value) => Number.isFinite(value));
  const low = (): number => props.min ?? 0;
  const high = (): number => {
    const top = props.max ?? Math.max(0, ...values());
    // one range for a flat map: every cell lands on the same colour instead of dividing by nothing
    return top === low() ? low() + 1 : top;
  };
  const columns = (): number => Math.max(1, props.columns.length);
  const show = (value: number): string => (props.format ?? String)(value);

  const own = {
    "data-part": "heatmap",
    get class() {
      return css.cn(table, props.class);
    },
    get style() {
      return {
        // the count is the caller's, so the grid is spelled out: `repeat()` cannot take a custom property (kebab-case: a
        // camelCase key is dropped by the style object's writer, which only sets the names it knows)
        "grid-template-columns": `minmax(2.5rem, max-content) repeat(${columns()}, minmax(0, 1fr))`,
        "--min": low(),
        "--max": high(),
        // a token is build-time text: a run-time style names the custom property the theme declares
        "--heat-hot": "var(--color-highlight)",
        "--heat-cold": "var(--color-button-background)",
      } as never;
    },
  } as unknown as PartProps;

  return (
    <figure data-part="heatmap-frame" class={frame}>
      <button
        type="button"
        data-part="heatmap-toggle"
        class={css.cn(toggle, toggles)}
        aria-pressed={numbers() ? "true" : "false"}
        onClick={() => setNumbers((on) => !on)}
      >
        {numbers() ? "Show the colours" : "Show the numbers"}
      </button>
      {renderPart(props, own, undefined, (part) => (
        <table {...part}>
          <caption data-part="heatmap-caption" class={caption}>
            {props.label}
            {props.unit === undefined ? "" : `, in ${props.unit}`}
          </caption>
          <thead class={head}>
            <tr class={row}>
              {/* the corner is empty and says nothing: it is the grid's first cell, not a header */}
              <td aria-hidden="true" class={corner} />
              <For each={props.columns}>
                {(name) => (
                  <th scope="col" class={column}>
                    {name}
                  </th>
                )}
              </For>
            </tr>
          </thead>
          <tbody class={body}>
            <For each={props.rows}>
              {(entry) => (
                <tr class={row}>
                  <th scope="row" class={label}>
                    {entry.label}
                  </th>
                  <For each={props.columns}>
                    {(_, index) => {
                      const value = (): number | undefined => entry.values[index()];
                      return (
                        <td
                          data-part="heatmap-cell"
                          class={value() === undefined ? empty : numbers() ? cellOpen : cell}
                          style={
                            {
                              "--v": value() ?? low(),
                            } as never
                          }
                        >
                          <span class={numbers() ? textOpen : text}>
                            {value() === undefined ? "" : show(value() as number)}
                          </span>
                        </td>
                      );
                    }}
                  </For>
                </tr>
              )}
            </For>
          </tbody>
        </table>
      ))}
      <p data-part="heatmap-scale" class={scale}>
        {`${show(low())} to ${show(high())}${props.unit === undefined ? "" : ` ${props.unit}`}; darker is more.`}
      </p>
    </figure>
  );
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

// The heatmap's conformance: the table is the data and the colour is CSS. The tests read what a reader gets — a header per
// column, a label per row, one cell per pair with its number, a colour that follows the value, and the scale in words — not
// the stylesheet that produced it.
import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import { describe, expect, it } from "vite-plus/test";
import { userEvent } from "vite-plus/test/browser";

import { Heatmap, type HeatmapRow } from "./heatmap.tsx";

const mount = (element: () => JSX.Element) => {
  const root = document.createElement("div");
  document.body.append(root);
  const dispose = render(element, root);
  return {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

const ROWS: ReadonlyArray<HeatmapRow> = [
  { label: "Mon", values: [0, 4, 8] },
  { label: "Tue", values: [2, 6, 1] },
];
const COLUMNS = ["08", "09", "10"];

const table = (root: HTMLElement): HTMLElement =>
  root.querySelector<HTMLElement>('[data-part="heatmap"]')!;
const cells = (root: HTMLElement): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>('[data-part="heatmap-cell"]'),
];

describe("Heatmap", () => {
  it("is a table: a header per column, a label per row and a cell per pair", () => {
    const { root, dispose } = mount(() => (
      <Heatmap label="Deploys by hour" columns={COLUMNS} rows={ROWS} unit="deploys" />
    ));
    expect(root.querySelectorAll('th[scope="col"]')).toHaveLength(3);
    expect(root.querySelectorAll('th[scope="row"]')).toHaveLength(2);
    expect(cells(root)).toHaveLength(6);
    // the caption names the table and says what the numbers are
    expect(root.querySelector("caption")?.textContent).toBe("Deploys by hour, in deploys");
    // every value is the cell's text, so a reader hears it
    expect(cells(root).map((cell) => cell.textContent?.trim())).toEqual([
      "0",
      "4",
      "8",
      "2",
      "6",
      "1",
    ]);
    dispose();
  });

  it("colours a cell by its share of the scale, and keeps the scale on the table", () => {
    const { root, dispose } = mount(() => (
      <Heatmap label="Deploys" columns={COLUMNS} rows={ROWS} />
    ));
    const [first, , last] = cells(root);
    // the scale is the data's unless the page gives one
    expect(table(root).style.getPropertyValue("--max")).toBe("8");
    expect(table(root).style.getPropertyValue("--min")).toBe("0");
    // a bigger share is a different colour: the mix is the value's
    const low = getComputedStyle(first!).backgroundColor;
    const high = getComputedStyle(last!).backgroundColor;
    expect(low).not.toBe(high);
    dispose();
  });

  it("shows a cell's value on hover, over the square and without moving the grid", async () => {
    const { root, dispose } = mount(() => (
      <Heatmap label="Deploys" columns={COLUMNS} rows={ROWS} />
    ));
    const cell = cells(root)[1]!;
    const value = cell.querySelector<HTMLElement>("span")!;
    expect(getComputedStyle(value).fontSize).toBe("0px");
    await userEvent.hover(cell);
    expect(getComputedStyle(value).fontSize).not.toBe("0px");
    // the square is the grid item either way: the label's box does not change
    expect(cell.getBoundingClientRect().width).toBeGreaterThan(0);
    dispose();
  });

  it("shows every number without a pointer, from its own toggle", async () => {
    const { root, dispose } = mount(() => (
      <Heatmap label="Deploys" columns={COLUMNS} rows={ROWS} />
    ));
    const toggle = root.querySelector<HTMLButtonElement>('[data-part="heatmap-toggle"]')!;
    const cell = cells(root)[1]!;
    const value = cell.querySelector<HTMLElement>("span")!;

    // the colours first: the value is out of the way, and the button says what pressing it does
    expect(toggle.textContent?.trim()).toBe("Show the numbers");
    expect(toggle.getAttribute("aria-pressed")).toBe("false");
    expect(getComputedStyle(value).fontSize).toBe("0px");
    expect(getComputedStyle(cell).aspectRatio).toBe("1 / 1");

    toggle.click();
    // the same table, read: every number in place, the squares grown to their rows
    await Promise.resolve();
    expect(toggle.getAttribute("aria-pressed")).toBe("true");
    expect(toggle.textContent?.trim()).toBe("Show the colours");
    expect(getComputedStyle(value).fontSize).not.toBe("0px");
    expect(getComputedStyle(value).position).toBe("static");
    expect(getComputedStyle(cell).aspectRatio).toBe("auto");
    expect(cell.textContent?.trim()).toBe("4");
    dispose();
  });

  it("reads an empty cell as empty and puts the scale in words", () => {
    const { root, dispose } = mount(() => (
      <Heatmap
        label="Deploys"
        unit="deploys"
        columns={COLUMNS}
        rows={[
          { label: "Mon", values: [1, 2, 3] },
          { label: "Tue", values: [1, 2, 3] },
        ]}
        max={6}
      />
    ));
    expect(root.querySelector('[data-part="heatmap-scale"]')?.textContent).toBe(
      "0 to 6 deploys; darker is more.",
    );
    // the empty cell: no value, so no text and no colour of the scale
    const { root: other, dispose: stop } = mount(() => (
      <Heatmap label="Deploys" columns={["08", "09"]} rows={[{ label: "Mon", values: [1] }]} />
    ));
    const empty = cells(other)[1]!;
    expect(empty.textContent?.trim()).toBe("");
    expect(empty.style.getPropertyValue("--v")).toBe("0");
    dispose();
    stop();
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
